import React from "react";
import styles from "./TodayCard.module.css";

function MetricCard({ title, value, change }) {
  return (
    <div className={styles.metricCard}>
      <div className={styles.gradientBg} />
      <div className={styles.inner}>
        <div className={styles.circle}>
          <div className={styles.metricTitle}>{title}</div>
          <div className={styles.metricValue}>{value}</div>
        </div>

        <div className={styles.changeWrap}>
          <div className={styles.changeLabel}>전일 대비 증가</div>
          <div className={styles.pill}>
            <svg className={styles.arrow} width="14" height="14" viewBox="0 0 24 24" aria-hidden>
              <path d="M6 14l6-6 6 6" fill="none" stroke="currentColor" strokeWidth="2" />
            </svg>
            <span>+ {change}%</span>
          </div>
        </div>
      </div>
    </div>
  );
}

function EventItem({ date, time, title }) {
  return (
    <div className={styles.eventItem}>
      <div className={styles.eventTop}>
        <span className={styles.clock} aria-hidden />
        <span className={styles.dateBold}>{date}</span>
        <span className={styles.timeMuted}>{time}</span>
      </div>
      <div className={styles.eventDivider} />
      <div className={styles.eventTitle}>{title}</div>
    </div>
  );
}

export default function TodayCard() {
  const events = [
    { date: "8월 7일", time: "17 : 00", title: "일자리창출지원사업 참여자 모집" },
    { date: "8월 7일", time: "17 : 00", title: "일자리창출지원사업 참여자 모집" },
    { date: "8월 7일", time: "17 : 00", title: "일자리창출지원사업 참여자 모집" },
  ];

  return (
    <section className={styles.section}>
      <div className={styles.headerRow}>
        <h2 className={styles.leftTitle}>오늘의 서산</h2>
        <h2 className={styles.rightTitle}>
          다가오는 이벤트 <span className={styles.emoji} aria-hidden>📣</span>
        </h2>
      </div>

      <div className={styles.layout}>
        <div className={styles.metrics}>
          <MetricCard title="전체 콘텐츠" value="1,432" change={12} />
          <MetricCard title="오늘의 수집" value="18" change={7} />
        </div>

        <div className={styles.events}>
          {events.map((e, i) => (
            <EventItem key={i} date={e.date} time={e.time} title={e.title} />
          ))}
        </div>
      </div>
    </section>
  );
}
